"""Review and hash the original source packet for an LVMC lamp capture.

The packet requests a construction. It cannot itself prove realized lamp output,
visibility, covered status, or a legal conclusion.
"""

import argparse
from datetime import datetime
import hashlib
import json
import math
from pathlib import Path


ASSIGNMENT = "testing__C230286__LVMC-11-38-120-B__motorcycle_or_moped_operator"
SOURCE_NAMES = (
    "map_opendrive", "vehicle_coverage", "road_sidewalk_geometry",
    "astronomical_times", "light_atmosphere", "discernibility_protocol",
    "headlamp_photometry", "tail_lamp_photometry",
)
REQUESTS = {
    "coverage_request": {"covered_motorcycle", "trail_ride_exclusion_probe",
                         "enclosed_three_wheel_exclusion_probe"},
    "illumination_request": {"night", "day_clear", "day_lowlight", "day_atmosphere",
                             "clear_atmosphere"},
    "motion_request": {"moving", "stopped"},
    "lit_state_request": {"both_lit", "both_off", "head_off", "tail_off"},
    "calibrated_lamp_request": {
        "white_300_red_500", "white_299_red_500", "white_301_red_500",
        "white_300_red_499", "white_300_red_501", "nonwhite_300_red_500",
        "white_300_nonred_500",
    },
    "timing_request": {"night", "day", "sunset_plus_29min", "sunset_plus_30min",
                       "sunset_plus_31min", "sunrise_minus_31min",
                       "sunrise_minus_30min", "sunrise_minus_29min"},
}


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _number(value, label):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError(label + " must be a finite original number")
    return float(value)


def verify(packet_path, *, diagnostic_fixture=False):
    packet_path = Path(packet_path)
    packet = json.loads(packet_path.read_text(encoding="utf-8"))
    if packet.get("assignment_id") != ASSIGNMENT:
        raise ValueError("source packet assignment mismatch")
    case_id = packet.get("case_id")
    if not isinstance(case_id, str) or not case_id.startswith(ASSIGNMENT + "__"):
        raise ValueError("source packet exact case mismatch")
    if packet.get("source_kind") != ("diagnostic_fixture" if diagnostic_fixture else "original_reviewed"):
        raise ValueError("reviewed original source packet required")
    refs = packet.get("source_refs")
    if not isinstance(refs, dict) or set(refs) != set(SOURCE_NAMES):
        raise ValueError("all independent original source references required")
    for name, ref in refs.items():
        if not isinstance(ref, dict) or set(ref) != {"path", "sha256", "reviewed_by", "method"}:
            raise ValueError("incomplete original source reference: " + name)
        path = Path(ref["path"])
        if path.is_absolute() or ".." in path.parts or len(path.parts) != 1:
            raise ValueError("source reference must be a sibling file: " + name)
        original = packet_path.parent / path
        if not original.is_file() or sha(original) != ref["sha256"]:
            raise ValueError("missing or changed original source: " + name)
        if not ref["reviewed_by"] or not ref["method"]:
            raise ValueError("source review provenance missing: " + name)
    scene = packet.get("scene")
    if not isinstance(scene, dict):
        raise ValueError("source-grounded scene required")
    for key in ("cell_id", "law_id", "actor", "map_name", "vehicle_blueprint",
                "route", "sidewalk", "local_datetime", "sunset_local", "sunrise_local",
                *REQUESTS):
        if key not in scene:
            raise ValueError("source-grounded scene field missing: " + key)
    if (scene["cell_id"], scene["law_id"], scene["actor"]) != (
            "C230286", "LVMC-11-38-120-B", "motorcycle_or_moped_operator"):
        raise ValueError("source-grounded scene identity mismatch")
    if scene["route"].get("surface") != "roadway" or scene["sidewalk"].get("surface") != "sidewalk":
        raise ValueError("roadway travel and separate sidewalk geometry required")
    if scene["route"].get("sidewalk_relation") != "adjacent_separate":
        raise ValueError("fixed sidewalk relation changed")
    if not scene["route"].get("waypoints") or not scene["sidewalk"].get("polygon"):
        raise ValueError("source surveyed route and sidewalk polygon required")
    if not scene["map_name"] or not scene["vehicle_blueprint"]:
        raise ValueError("reviewed map and motorcycle blueprint required")
    for key, allowed in REQUESTS.items():
        if scene[key] not in allowed:
            raise ValueError("invalid controlled request: " + key)
    if scene["coverage_request"] != "covered_motorcycle" and scene["vehicle_blueprint"] == "":
        raise ValueError("coverage control vehicle required")
    if not all(isinstance(scene[x], str) and scene[x] for x in (
            "local_datetime", "sunset_local", "sunrise_local")):
        raise ValueError("original astronomical timing required")
    try:
        astronomical_source = json.loads((packet_path.parent / refs["astronomical_times"]["path"])
                                        .read_text(encoding="utf-8"))
    except (OSError, ValueError) as error:
        raise ValueError("readable original astronomical source required") from error
    if any(astronomical_source.get(key) != scene[key] for key in
           ("local_datetime", "sunset_local", "sunrise_local")):
        raise ValueError("astronomical source differs from requested scene")
    try:
        local_time = datetime.fromisoformat(scene["local_datetime"])
        sunset = datetime.fromisoformat(scene["sunset_local"])
        sunrise = datetime.fromisoformat(scene["sunrise_local"])
        if any(value.tzinfo is None for value in (local_time, sunset, sunrise)):
            raise ValueError("timezone-aware original astronomical timing required")
        since_sunset = (local_time - sunset).total_seconds() / 60
        before_sunrise = (sunrise - local_time).total_seconds() / 60
    except (TypeError, ValueError) as error:
        raise ValueError("valid original astronomical timing required") from error
    timing = scene["timing_request"]
    if timing.startswith("sunset_plus_"):
        expected = int(timing.removeprefix("sunset_plus_").removesuffix("min"))
        if abs(since_sunset - expected) > 0.001:
            raise ValueError("sunset offset request differs from source time")
    if timing.startswith("sunrise_minus_"):
        expected = int(timing.removeprefix("sunrise_minus_").removesuffix("min"))
        if abs(before_sunrise - expected) > 0.001:
            raise ValueError("sunrise offset request differs from source time")
    if _number(scene.get("duration_s"), "duration_s") <= 0 or scene.get("rate_hz") != 20:
        raise ValueError("positive duration and 20 Hz capture required")
    if _number(scene.get("requested_speed_mps"), "requested_speed_mps") < 0:
        raise ValueError("negative requested speed")
    if _number(scene.get("discernibility_request_ft"), "discernibility_request_ft") < 0:
        raise ValueError("negative discernibility request")
    return {"assignment_id": ASSIGNMENT, "case_id": case_id,
            "packet_sha256": sha(packet_path),
            "source_hashes": {name: ref["sha256"] for name, ref in refs.items()},
            "requested_controls": {**{name: scene[name] for name in REQUESTS},
                                   "discernibility_request_ft": scene["discernibility_request_ft"]},
            "astronomical_offsets_minutes": {"since_sunset": since_sunset,
                                             "before_sunrise": before_sunrise},
            "physical_acceptance": "unverified"}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--packet", required=True)
    parser.add_argument("--diagnostic-fixture", action="store_true")
    args = parser.parse_args()
    print(json.dumps(verify(args.packet, diagnostic_fixture=args.diagnostic_fixture), sort_keys=True))


if __name__ == "__main__":
    main()

"""Controlled lamp and motion requests for one source-reviewed motorcycle case.

The adapter must read back actual actor state and original camera frames. Requests
are never substituted for observations or calibrated lamp capability.
"""

import json
from pathlib import Path

from source_packet import ASSIGNMENT, verify as verify_source


LAMP_STATES = {
    "both_lit": (True, True),
    "head_off": (False, True),
    "tail_off": (True, False),
    "both_off": (False, False),
}


def prepare(adapter, packet_path, case_plan_path, *, diagnostic_fixture=False):
    verified = verify_source(packet_path, diagnostic_fixture=diagnostic_fixture)
    plan = json.loads(Path(case_plan_path).read_text(encoding="utf-8"))
    exact = next((case for case in plan["cases"] if case["case_id"] == verified["case_id"]), None)
    if exact is None or plan["assignment_id"] != ASSIGNMENT:
        raise ValueError("exact source packet case not in selected plan")
    scene = json.loads(Path(packet_path).read_text(encoding="utf-8"))["scene"]
    for name in ("coverage_request", "illumination_request", "motion_request",
                 "calibrated_lamp_request", "lit_state_request", "timing_request",
                 "discernibility_request_ft"):
        if scene[name] != exact[name]:
            raise ValueError("controlled case request differs: " + name)
    if not callable(getattr(adapter, "loaded_map_bytes", None)):
        raise ValueError("original Native map readback required")
    if verified["source_hashes"]["map_opendrive"] != adapter.sha_bytes(adapter.loaded_map_bytes()):
        raise ValueError("loaded Native map differs from reviewed OpenDRIVE")
    if not callable(getattr(adapter, "verify_sidewalk", None)) or not adapter.verify_sidewalk(
            scene["route"], scene["sidewalk"]):
        raise ValueError("roadway and separate physical sidewalk readback failed")
    if not callable(getattr(adapter, "spawn_vehicle", None)):
        raise ValueError("Native motorcycle spawn required")
    ego = adapter.spawn_vehicle(scene["vehicle_blueprint"], scene["route"])
    if not callable(getattr(adapter, "vehicle_blueprint_id", None)) or \
            adapter.vehicle_blueprint_id(ego) != scene["vehicle_blueprint"]:
        raise ValueError("spawned motorcycle blueprint differs")
    head, tail = LAMP_STATES[scene["lit_state_request"]]
    if not callable(getattr(adapter, "set_lamps", None)) or not adapter.set_lamps(ego, head, tail):
        raise ValueError("independent head and tail lamp control not applied")
    if not callable(getattr(adapter, "read_lamps", None)) or adapter.read_lamps(ego) != (head, tail):
        raise ValueError("independent head and tail lamp readback failed")
    if not callable(getattr(adapter, "set_weather", None)) or not adapter.set_weather(scene):
        raise ValueError("original weather and sun setup failed")
    if not callable(getattr(adapter, "read_weather", None)) or not adapter.read_weather(scene):
        raise ValueError("original weather and sun readback failed")
    if not callable(getattr(adapter, "set_route", None)) or not adapter.set_route(
            ego, scene["route"], scene["requested_speed_mps"]):
        raise ValueError("source-grounded roadway route control failed")
    return {"case_id": exact["case_id"], "ego": ego,
            "source_packet_sha256": verified["packet_sha256"],
            "requested_lamps": {"head": head, "tail": tail},
            "observed_lamps_initial": {"head": head, "tail": tail},
            "physical_completion": "unverified"}

"""Source-bound motion, lamp and photometry observations for LVMC 11.38.120.

This does not infer legal visibility or covered-vehicle status from appearance.
"""

import argparse
from datetime import datetime
import hashlib
import json
import math
from pathlib import Path

ASSIGNMENT_ID = "testing__C230286__LVMC-11-38-120-B__motorcycle_or_moped_operator"
SOURCE_BINDINGS = {
    "vehicle_blueprint_source": "vehicle_coverage",
    "section_080_coverage_source": "vehicle_coverage",
    "trail_ride_source": "vehicle_coverage",
    "enclosed_three_wheel_source": "vehicle_coverage",
    "road_sidewalk_source": "road_sidewalk_geometry",
    "local_date_time_source": "astronomical_times",
    "sunset_sunrise_source": "astronomical_times",
    "light_atmosphere_source": "light_atmosphere",
    "discernibility_500ft_source": "discernibility_protocol",
    "headlamp_calibration_source": "headlamp_photometry",
    "tail_lamp_calibration_source": "tail_lamp_photometry",
}


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def finite_nonnegative(value):
    if not isinstance(value, (int, float)) or not math.isfinite(value) or value < 0:
        raise ValueError("finite nonnegative original measurement required")
    return value


def measure(case_id, context_path, trace_path, receipt_path, *, diagnostic_fixture=False):
    if not case_id.startswith(ASSIGNMENT_ID + "__"):
        raise ValueError("exact assignment case required")
    receipt = json.loads(Path(receipt_path).read_text(encoding="utf-8"))
    if (receipt.get("assignment_id"), receipt.get("case_id")) != (ASSIGNMENT_ID, case_id):
        raise ValueError("original source receipt identity mismatch")
    if (receipt.get("diagnostic_fixture") is not diagnostic_fixture or
            receipt.get("source_kind") != ("diagnostic_fixture" if diagnostic_fixture else
                                           "original_native_capture")):
        raise ValueError("original Native capture required unless explicitly diagnostic")
    if receipt.get("context_sha256") != sha(context_path) or receipt.get("trace_sha256") != sha(trace_path):
        raise ValueError("original source bytes changed")
    context = json.loads(Path(context_path).read_text(encoding="utf-8"))
    if context.get("case_id") != case_id or not isinstance(context.get("map_sha256"), str) or len(context["map_sha256"]) != 64:
        raise ValueError("exact source map context required")
    refs = context.get("source_refs")
    if not isinstance(refs, dict) or set(refs) != set(SOURCE_BINDINGS.values()) | {"map_opendrive"}:
        raise ValueError("complete original source hash inventory required")
    for name, ref in refs.items():
        if not isinstance(ref, dict) or set(ref) != {"path", "sha256"}:
            raise ValueError("original source path and hash required: " + name)
        path = Path(ref["path"])
        if path.is_absolute() or len(path.parts) != 1 or ".." in path.parts:
            raise ValueError("original source must be a sibling file: " + name)
        if sha(Path(context_path).parent / path) != ref["sha256"]:
            raise ValueError("original source bytes changed: " + name)
    if context["map_sha256"] != refs["map_opendrive"]["sha256"]:
        raise ValueError("original map source hash mismatch")
    for key, name in SOURCE_BINDINGS.items():
        if context.get(key) != refs[name]["sha256"]:
            raise ValueError("original context source mismatch: " + key)
    for key in ("local_datetime", "sunset_local", "sunrise_local"):
        if not isinstance(context.get(key), str) or not context[key]:
            raise ValueError("original local timing missing: " + key)
    try:
        local_time, sunset, sunrise = (datetime.fromisoformat(context[key]) for key in
                                       ("local_datetime", "sunset_local", "sunrise_local"))
        if any(value.tzinfo is None for value in (local_time, sunset, sunrise)):
            raise ValueError("original local timing must include timezone")
    except ValueError as error:
        raise ValueError("valid timezone-aware original local timing required") from error
    head, tail = context.get("headlamp_calibration"), context.get("tail_lamp_calibration")
    if not isinstance(head, dict) or not isinstance(tail, dict):
        raise ValueError("original calibrated lamp inventory required")
    for lamp in (head, tail):
        if lamp.get("emitted_color") not in {"white", "red", "other"} or not isinstance(lamp.get("mounted_position"), str):
            raise ValueError("original lamp color and mount required")
        finite_nonnegative(lamp.get("tested_visibility_ft"))
    discernibility = finite_nonnegative(context.get("observed_discernibility_ft"))
    if head.get("mounted_position") != "front" or tail.get("mounted_position") != "rear":
        raise ValueError("front headlamp and rear tail lamp required")
    rows = [json.loads(line) for line in Path(trace_path).read_text(encoding="utf-8").splitlines() if line]
    if len(rows) < 2 or len(rows) != receipt.get("frame_count") or receipt.get("fps") != 20:
        raise ValueError("original 20 Hz frame count mismatch")
    observations = []
    for index, row in enumerate(rows):
        if row.get("frame") != index or not isinstance(row.get("time_s"), (int, float)) or abs(row["time_s"] - index / 20) > .002:
            raise ValueError("original frame cadence mismatch")
        carla_frame = row.get("carla_frame")
        if carla_frame is not None and (type(carla_frame) is not int or carla_frame < 0):
            raise ValueError("original CARLA frame identity required")
        speed = finite_nonnegative(row.get("speed_mps"))
        if type(row.get("headlamp_burning")) is not bool or type(row.get("tail_lamp_burning")) is not bool:
            raise ValueError("independent original lamp burning states required")
        observations.append({"frame": index, "time_s": row["time_s"], "speed_mps": speed,
                             "carla_frame": carla_frame,
                             "headlamp_burning": row["headlamp_burning"],
                             "tail_lamp_burning": row["tail_lamp_burning"]})
    motion = [row for row in observations if row["speed_mps"] > 0]
    lamp_summary = {
        "original_frames": len(observations),
        "moving_frames": len(motion),
        "moving_headlamp_burning_frames": sum(row["headlamp_burning"] for row in motion),
        "moving_taillamp_burning_frames": sum(row["tail_lamp_burning"] for row in motion),
        "moving_both_burning_frames": sum(row["headlamp_burning"] and row["tail_lamp_burning"]
                                           for row in motion),
    }
    return {"assignment_id": ASSIGNMENT_ID, "case_id": case_id,
            "source_bindings": {"context_sha256": sha(context_path), "trace_sha256": sha(trace_path),
                                "receipt_sha256": sha(receipt_path), "native_map_sha256": context["map_sha256"]},
            "original_local_timing": {k: context[k] for k in ("local_datetime", "sunset_local", "sunrise_local")},
            "astronomical_offsets_minutes": {
                "since_sunset": (local_time - sunset).total_seconds() / 60,
                "before_sunrise": (sunrise - local_time).total_seconds() / 60},
            "calibrated_headlamp": head, "calibrated_tail_lamp": tail,
            "observed_discernibility_ft": discernibility, "observations": observations,
            "lamp_motion_summary": lamp_summary,
            "headlamp_300ft_reference_only": 300, "tail_lamp_500ft_reference_only": 500,
            "half_hour_offset_minutes_reference_only": 30,
            "covered_vehicle_judgment": "unresolved", "visibility_judgment": "unresolved",
            "burning_requirement_judgment": "unresolved", "physical_acceptance": "unverified"}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("case", "context", "trace", "receipt", "output"):
        parser.add_argument("--" + name, required=True)
    args = parser.parse_args()
    result = measure(args.case, args.context, args.trace, args.receipt)
    Path(args.output).write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
